public List<HistoryDTO> getHistoryPage(Integer page, String username) {
    long startTime = System.currentTimeMillis();

    // Find user and log time taken
    Users user = userRepository.findByUsername(username);
    log.info("Retrieved user {} in {} ms", username, System.currentTimeMillis() - startTime);

    // Get pending replays for the page
    Pageable pageable = PageRequest.of(page, 10, Sort.Direction.DESC, "createdDate");
    List<DbReplay> dbReplays = replayStrategy.getPendingReplays(user.getId(), pageable);
    log.info("Retrieved {} pending replays in {} ms", dbReplays.size(), System.currentTimeMillis() - startTime);

    // Return empty list if no replays found
    if (dbReplays.isEmpty()) {
        return new ArrayList<>();
    }

    // Process each replay to create history DTOs
    List<HistoryDTO> historyList = dbReplays.stream()
        .filter(dbReplay -> !dbReplay.getStatus().equals(ReplayStatus.FRESH))
        .map(dbReplay -> {
            long mapStartTime = System.currentTimeMillis();
            return processReplay(dbReplay, mapStartTime);
        })
        .filter(Objects::nonNull)
        .collect(Collectors.toList());

    // Save processed replays
    replayRepository.saveAll(dbReplays);

    log.info("Retrieved {} upload history DTOs in {} ms", historyList.size(), System.currentTimeMillis() - startTime);
    return historyList;
}

private HistoryDTO processReplay(DbReplay dbReplay, long mapStartTime) {
    List<ReplayRequest> replayRequestList = replayRequestRepository.findAllByReplayId(dbReplay.getId());

    if (replayRequestList.isEmpty()) {
        return null;
    }

    String highlightedPlayer = replayRequestList.get(0).getHighlightedPlayer();
    RiotApiHost region = matchMetadataStrategy.sanitizeAndGetMatchMetadata(dbReplay.getMatchId()).getRegion();
    MatchDetailsDTO matchDetails = getMatchDetails(dbReplay, replayRequestList.get(0), mapStartTime);

    return uploadHistoryStrategy.getUploadHistoryDTO(dbReplay, matchDetails);
}

private MatchDetailsDTO getMatchDetails(DbReplay dbReplay, ReplayRequest replayRequest, long mapStartTime) {
    MatchDetailsDTO matchDetails;

    if (!StringUtils.isNullOrEmpty(replayRequest.getMatchDetailsJson())) {
        try {
            matchDetails = objectMapper.readValue(replayRequest.getMatchDetailsJson(), MatchDetailsDTO.class);
            log.info("Loaded history DTO for replay {} in {} ms", dbReplay.getId(), System.currentTimeMillis() - mapStartTime);
        } catch (JsonProcessingException e) {
            e.printStackTrace();
            return null;
        }
    } else {
        MatchDetailsRequest matchDetailsRequest = new MatchDetailsRequest(dbReplay.getMatchId(), replayRequest.getHighlightedPlayer(), region);
        matchDetails = matchDetailsService.getMatchDetails(matchDetailsRequest);
        try {
            replayRequest.setMatchDetailsJson(objectMapper.writeValueAsString(matchDetails));
            log.info("Created history DTO for replay {} in {} ms", dbReplay.getId(), System.currentTimeMillis() - mapStartTime);
        } catch (JsonProcessingException e) {
            e.printStackTrace();
            return null;
        }
    }
    return matchDetails;
}
