import React, { useState, useRef, useEffect } from "react";
import { TextField } from '@mui/material';
import styled from 'styled-components';
import { KTSVG } from "../../_metronic/helpers";

const StyledTextField = styled(TextField)`
  & label {
    font-family: 'Poppins';
    font-size: 18px;
    color: #aaa;
  }

  & .MuiOutlinedInput-input {
    font-family: 'Poppins';
    font-size: 15px;
  }

  & label.Mui-error.Mui-focused {
    color: #d32f2f;
  }

  & .MuiOutlinedInput-notchedOutline {
    border-color: #e4e6ef;
    font-size: 20px;
  }

  &:hover .MuiOutlinedInput-notchedOutline {
    border-color: #ccc;
  }

  & .MuiOutlinedInput-root.Mui-focused .MuiOutlinedInput-notchedOutline {
    border-color: #ccc;
    border-width: 1px;
  }

  & .MuiInputLabel-root.Mui-focused {
    color: #aaa;
  }

  & .MuiOutlinedInput-root:hover fieldset {
    border-color: #ccc;
  }

  & .MuiOutlinedInput-root.Mui-error:hover .MuiOutlinedInput-notchedOutline,
  .MuiOutlinedInput-root.Mui-error.Mui-focused .MuiOutlinedInput-notchedOutline {
    border-color: #d32f2f !important;
  }

  & .MuiFormHelperText-root.Mui-error {
    font-family: 'Poppins';
    font-size: 12px;
  }
`;

const EditableLabel: React.FC = ({ id, name, value, onChange, onBlur, touched, errors, readOnly }) => {
  const [isEditable, setIsEditable] = useState(false);
  const [isHovered, setIsHovered] = useState(false);
  const [isFocused, setIsFocused] = useState(false);
  const inputRef = useRef(null);

  const handleLabelClick = () => {
    setIsEditable(true);
    setIsFocused(true);
    setIsHovered(false);
  };

  const handleInputBlur = () => {
    setIsFocused(false);
    setIsEditable(false);
  };

  const textFieldStyle: React.CSSProperties = {
    fontSize: "inherit",
    fontWeight: "inherit",
    backgroundColor: "#f4f7f9",
    cursor: "pointer",
    minWidth: "300px",
    marginLeft: 10
  };

  const labelStyle: React.CSSProperties = {
    fontSize: "inherit",
    fontWeight: "inherit",
    backgroundColor: "transparent",
    cursor: "pointer",
    paddingTop: 20,
    paddingBottom: 20,
    paddingRight: 40,
    paddingLeft: 15,
    borderRadius: 5,
    marginLeft: 5,
    position: "relative"
  };

  const labelHoverStyle: React.CSSProperties = {
    backgroundColor: "#f4f7f9",
  };

  const editIconStyle: React.CSSProperties = {
    position: "absolute",
    right: "4%",
    top: "45%",
    transform: "translateY(-50%)",
    width: "16px",
    height: "16px",
    display: "block",
    fill: "#555",
    cursor: "pointer",
  };

  useEffect(() => {
    if (isEditable && inputRef.current) {
      inputRef.current?.focus();
    }
  }, [isEditable, inputRef]);

  return (
    {isEditable ? (
      <StyledTextField
        id={id}
        name={name}
        value={value}
        onChange={onChange}
        onBlur={handleInputBlur}
        error={touched && Boolean(errors)}
        helperText={touched && errors}
        inputRef={inputRef}
        inputProps={{ style: textFieldStyle }}
        InputLabelProps={{ style: labelStyle }}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        onClick={handleLabelClick}
      />
    ) : (
      <div
        style={labelStyle}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        onClick={handleLabelClick}
      >
        {value}
        {isHovered && (
          <div style={editIconStyle}>
            <KTSVG path="/media/icons/duotune/art/art005.svg" className="svg-icon-2" />
          </div>
        )}
      </div>
    )}
  );
};

export default EditableLabel;
```

